mapper.select:
select coalesce(max(sequence_no), 0)
from ai_agent_message
where conversation_id = #{conversationId}

select id, tenant_id, conversation_id, run_id, sequence_no, role, content,
       message_status, citations, create_time, update_time
from ai_agent_message
where conversation_id = #{conversationId}

    and sequence_no < #{beforeSequence}

order by sequence_no desc
limit #{size}
